  &reftitle.parameters;




     codepoint


0 र 255 बीचको एउटा integer।

मान्य range (0..255) बाहिरका Values लाई 255 सँग bitwise AND गरिनेछ, जुन निम्न algorithm सँग समान हुन्छ:

while ($bytevalue < 0) {
    $bytevalue += 256;
}
$bytevalue %= 256;

&reftitle.changelog;





    &Version;
    &Description;





    8.5.0
    [0, 255] interval बाहिरका integers pass गर्ने कार्य अब deprecated गरिएको छ।



    7.4.0
    यो function ले अब unsupported codepoint हरूलाई silently स्वीकार गर्दैन र तिनीहरूलाई 0 मा cast गर्दैन।

  &reftitle.examples;



    chr को उदाहरण


<?php
// Assumes the string will be used as ASCII or an ASCII-compatible encoding

$str = "The string ends in escape: ";
$str .= chr(27); /* add an escape character at the end of $str */
echo $str, PHP_EOL;

/* Often this is more useful */
$str = sprintf("The string ends in escape: %c", 27);
echo $str, PHP_EOL;
?>







    Overflow व्यवहार


<?php
echo chr(-159), chr(833), PHP_EOL;
?>


